window.Howl=function(options){this.options=options||{};this.audio=null;this.play=()=>{try{this.audio=this.audio||new Audio((this.options.src||[])[0]);this.audio.loop=!!this.options.loop;this.audio.volume=this.options.volume??1;this.audio.play().catch(()=>{});}catch{}};this.pause=()=>{if(this.audio)this.audio.pause();}};
